def rot(axis,a):
 axis=np.array(axis,float); axis/=np.linalg.norm(axis); x,y,z=axis; c=np.cos(a); t=np.sin(a); C=1-c
 return np.array([[c+x*x*C,x*y*C-z*t,x*z*C+y*t],[y*x*C+z*t,c+y*y*C,y*z*C-x*t],[z*x*C-y*t,z*y*C+x*t,c+z*z*C]])
def fk(side,p,roll,yaw,elbow,torso):
 sign=1 if side=='L' else -1
 sp=np.array([.005,sign*.155,.43]); sr=np.array([0,sign*.214,.439]); sy=np.array([0,sign*.214,.305]); el=np.array([.018,sign*.214,.107]); hand=np.array([.639,sign*.214,.087])
 axp=s['proprio']['axis'][11 if side=='L' else 15]; axr=s['proprio']['axis'][12 if side=='L' else 16]; axy=s['proprio']['axis'][13 if side=='L' else 17]; axe=s['proprio']['axis'][14 if side=='L' else 18]
 Rp=rot(axp,p); Rr=rot(axr,roll); Ry=rot(axy,yaw); Re=rot(axe,elbow)
 v=(sr-sp)+Rp.T@((sy-sr)+Rr.T@((el-sy)+Ry.T@(hand-el)))
